125	// validatePodAutoscaler performs all spec validations.
126	func (v *PodAutoscalerCustomValidator) validatePodAutoscaler(pa *autoscalingv1alpha1.PodAutoscaler) error {
127		var allErrs field.ErrorList
128		specPath := field.NewPath("spec")
129	
130		// 1. Validate ScaleTargetRef
131		targetRef := pa.Spec.ScaleTargetRef
132		targetRefPath := specPath.Child("scaleTargetRef")
133		if targetRef.Name == "" {
134			allErrs = append(allErrs, field.Required(targetRefPath.Child("name"), "must be set"))
135		}
136		if targetRef.Kind == "" {
137			allErrs = append(allErrs, field.Required(targetRefPath.Child("kind"), "must be set"))
138		}
139	
140		// 2. Validate Replica Bounds
141		if pa.Spec.MinReplicas != nil && pa.Spec.MaxReplicas < *pa.Spec.MinReplicas {
142			minPath := specPath.Child("minReplicas")
143			maxPath := specPath.Child("maxReplicas")
144			allErrs = append(allErrs,
145				field.Invalid(minPath, pa.Spec.MinReplicas, "cannot be greater than maxReplicas"),
146				field.Invalid(maxPath, pa.Spec.MaxReplicas, "cannot be less than minReplicas"),
147			)
148		}
149	
150		allErrs = append(allErrs, validateMetricWindows(pa, specPath)...)
151	
152		// 3. Validate ScalingStrategy
153		validStrategies := map[autoscalingv1alpha1.ScalingStrategyType]bool{
154			autoscalingv1alpha1.HPA: true,
155			autoscalingv1alpha1.KPA: true,
156			autoscalingv1alpha1.APA: true,
157		}
158		if !validStrategies[pa.Spec.ScalingStrategy] {
159			strategyPath := specPath.Child("scalingStrategy")
160			allErrs = append(allErrs, field.NotSupported(strategyPath, pa.Spec.ScalingStrategy, []string{
161				string(autoscalingv1alpha1.HPA),
162				string(autoscalingv1alpha1.KPA),
163				string(autoscalingv1alpha1.APA),
164			}))
165		}
166		if err := validateHPARoleSubtarget(pa, specPath); err != nil {
167			allErrs = append(allErrs, err)
168		}
169	
170		// 4. Validate MetricsSources
171		metricsPath := specPath.Child("metricsSources")
172		if len(pa.Spec.MetricsSources) != 1 {
173			allErrs = append(allErrs, field.Invalid(metricsPath, pa.Spec.MetricsSources, "exactly one metricsSource is required"))
174		} else {
175			ms := &pa.Spec.MetricsSources[0]
176			msPath := metricsPath.Index(0)
177	
178			if ms.TargetMetric == "" {
179				allErrs = append(allErrs, field.Required(msPath.Child("targetMetric"), "must be set"))
180			}
181			if ms.TargetValue == "" {
182				allErrs = append(allErrs, field.Required(msPath.Child("targetValue"), "must be set"))
183			} else {
184				qty, err := resource.ParseQuantity(ms.TargetValue)
185				if err != nil {
186					allErrs = append(allErrs, field.Invalid(msPath.Child("targetValue"), ms.TargetValue, "must be a valid number"))
187				} else {
188					if qty.Sign() <= 0 {
189						allErrs = append(allErrs, field.Invalid(msPath.Child("targetValue"), ms.TargetValue, "must be greater than 0"))
190					}
191				}
192			}
193	
194			switch ms.MetricSourceType {
195			case autoscalingv1alpha1.POD:
196				if ms.ProtocolType == "" {
197					allErrs = append(allErrs, field.Required(msPath.Child("protocolType"), "required for metricSourceType=pod"))
198				}
199				if ms.Port == "" {
200					allErrs = append(allErrs, field.Required(msPath.Child("port"), "required for metricSourceType=pod"))
201				}
202				if ms.Path == "" {
203					allErrs = append(allErrs, field.Required(msPath.Child("path"), "required for metricSourceType=pod"))
204				}
205	
206			case autoscalingv1alpha1.EXTERNAL, autoscalingv1alpha1.DOMAIN:
207				// Empty endpoint selects the Kubernetes external.metrics API instead of an HTTP metrics endpoint.
208				if ms.Endpoint == "" {
209					break
210				}
211				if ms.ProtocolType == "" {
212					allErrs = append(allErrs, field.Required(msPath.Child("protocolType"), "required for metricSourceType=external/domain"))
213				}
214				if ms.Endpoint == "" {
215					allErrs = append(allErrs, field.Required(msPath.Child("endpoint"), "required for metricSourceType=external/domain"))
216				}
217				if ms.Path == "" {
218					allErrs = append(allErrs, field.Required(msPath.Child("path"), "required for metricSourceType=external/domain"))
219				}
220	
221			case autoscalingv1alpha1.RESOURCE:
222				validMetrics := map[string]bool{"cpu": true, "memory": true}
223				if !validMetrics[ms.TargetMetric] {
224					allErrs = append(allErrs, field.NotSupported(msPath.Child("targetMetric"), ms.TargetMetric, []string{"cpu", "memory"}))
225				}
226				// Ensure no extra fields are set
227				if ms.Port != "" {
228					allErrs = append(allErrs, field.Forbidden(msPath.Child("port"), "not allowed for metricSourceType=resource"))
229				}
230				if ms.Endpoint != "" {
231					allErrs = append(allErrs, field.Forbidden(msPath.Child("endpoint"), "not allowed for metricSourceType=resource"))
232				}
233				if ms.Path != "" {
234					allErrs = append(allErrs, field.Forbidden(msPath.Child("path"), "not allowed for metricSourceType=resource"))
235				}
236				if ms.ProtocolType != "" {
237					allErrs = append(allErrs, field.Forbidden(msPath.Child("protocolType"), "not allowed for metricSourceType=resource"))
238				}
239	
240			case autoscalingv1alpha1.CUSTOM:
241				// No required fields for custom metrics
242				break
243	
244			default:
245				allErrs = append(allErrs, field.NotSupported(msPath.Child("metricSourceType"), ms.MetricSourceType, []string{
246					string(autoscalingv1alpha1.POD),
247					string(autoscalingv1alpha1.EXTERNAL),
248					string(autoscalingv1alpha1.DOMAIN),
249					string(autoscalingv1alpha1.RESOURCE),
250					string(autoscalingv1alpha1.CUSTOM),
251				}))
252			}
253		}
254	
255		if len(allErrs) == 0 {
256			return nil
257		}
258	
259		return apierrors.NewInvalid(
260			schema.GroupKind{Group: autoscalingv1alpha1.GroupVersion.Group, Kind: "PodAutoscaler"},
261			pa.Name,
262			allErrs,
263		)
264	}
265	
266	func validateHPARoleSubtarget(pa *autoscalingv1alpha1.PodAutoscaler, specPath *field.Path) *field.Error {
267		if pa.Spec.ScalingStrategy != autoscalingv1alpha1.HPA ||
268			pa.Spec.SubTargetSelector == nil ||
269			pa.Spec.SubTargetSelector.RoleName == "" {
270			return nil
271		}
272	
273		return field.Forbidden(
274			specPath.Child("subTargetSelector").Child("roleName"),
275			"not supported with scalingStrategy=HPA; use APA or KPA for StormService role-level autoscaling",
276		)
277	}
278	
279	func validateMetricWindows(pa *autoscalingv1alpha1.PodAutoscaler, specPath *field.Path) field.ErrorList {
280		var allErrs field.ErrorList
281	
282		observeWindow := defaultObserveWindowSeconds
283		if pa.Spec.ObserveWindowSeconds != nil {
284			observeWindow = *pa.Spec.ObserveWindowSeconds
285			if observeWindow <= 0 {
286				allErrs = append(allErrs, field.Invalid(specPath.Child("observeWindowSeconds"), observeWindow, "must be greater than 0"))
287			}
288			if observeWindow > maxMetricWindowSeconds {
289				allErrs = append(allErrs, field.Invalid(specPath.Child("observeWindowSeconds"), observeWindow, fmt.Sprintf("must be less than or equal to %d", maxMetricWindowSeconds)))
290			}
291		}
292	
293		panicWindow := defaultPanicWindowSeconds
294		if pa.Spec.PanicWindowSeconds != nil {
295			panicWindow = *pa.Spec.PanicWindowSeconds
296			if panicWindow <= 0 {
297				allErrs = append(allErrs, field.Invalid(specPath.Child("panicWindowSeconds"), panicWindow, "must be greater than 0"))
298			}
299			if panicWindow > maxMetricWindowSeconds {
300				allErrs = append(allErrs, field.Invalid(specPath.Child("panicWindowSeconds"), panicWindow, fmt.Sprintf("must be less than or equal to %d", maxMetricWindowSeconds)))
301			}
302		}
303		if panicWindow > observeWindow {
304			allErrs = append(allErrs, field.Invalid(specPath.Child("panicWindowSeconds"), panicWindow, "must be less than or equal to observeWindowSeconds"))
305		}
306	
307		return allErrs
308	}
