49	// Default implements webhook.Defaulter so a webhook will be registered for the type
50	func (r *StormServiceCustomDefaulter) Default(_ context.Context, obj runtime.Object) error {
51		stormService, ok := obj.(*orchestrationv1alpha1.StormService)
52		if !ok {
53			return fmt.Errorf("expected a StormService object but got %T", obj)
54		}
55	
56		// Only proceed if the sidecar injection annotation is present
57		if _, exists := stormService.GetAnnotations()[SidecarInjectionAnnotation]; !exists {
58			return nil
59		}
60	
61		// Skip if spec is nil
62		if stormService.Spec.Template.Spec == nil {
63			return nil
64		}
65	
66		// Inject sidecar into each role
67		r.injectAIBrixRuntime(stormService)
68	
69		return nil
70	}
