72	// injectAIBrixRuntime injects the aibrix-runtime sidecar into each Role's pod template
73	func (r *StormServiceCustomDefaulter) injectAIBrixRuntime(stormService *orchestrationv1alpha1.StormService) {
74		spec := stormService.Spec.Template.Spec
75	
76		// Get engine type from RoleSet template annotations, if specified
77		var engineType string
78		if annotations := stormService.Spec.Template.Annotations; annotations != nil {
79			if engine, exists := annotations[constants.ModelLabelEngine]; exists && engine != "" {
80				engineType = engine
81			}
82		}
83	
84		// Get sidecar image from stormService annotations; fall back to default if not set
85		var sidecarImage string
86		if annotations := stormService.GetAnnotations(); annotations != nil {
87			if image, exists := annotations[SidecarInjectionRuntimeImageAnnotation]; exists && image != "" {
88				sidecarImage = image
89			}
90		}
91	
92		if sidecarImage == "" {
93			sidecarImage = SidecarImage // default
94		}
95	
96		for i := range spec.Roles {
97			role := &spec.Roles[i]
98	
99			// Skip if sidecar already exists
100			if containsContainer(role.Template.Spec.Containers, SidecarName) {
101				continue
102			}
103	
104			currentEngineType := engineType
105			if currentEngineType == "" {
106				// fallback：get inference engine from primary containers
107				currentEngineType = inferEngineType(role.Template.Spec.Containers)
108			}
109	
110			// Ensure the artifacts download path is shared with the sidecar container
111			foundEmptyDirVolume := false
112			for i := range role.Template.Spec.Volumes {
113				v := &role.Template.Spec.Volumes[i]
114				if v.Name == DefaultAdapterVolumeName {
115					if v.EmptyDir == nil {
116						// Volume with same name exists but is not EmptyDir. Overwrite to ensure correct type.
117						v.VolumeSource = corev1.VolumeSource{
118							EmptyDir: &corev1.EmptyDirVolumeSource{},
119						}
120					}
121					foundEmptyDirVolume = true
122					break
123				}
124			}
125			if !foundEmptyDirVolume {
126				role.Template.Spec.Volumes = append(role.Template.Spec.Volumes, corev1.Volume{
127					Name: DefaultAdapterVolumeName,
128					VolumeSource: corev1.VolumeSource{
129						EmptyDir: &corev1.EmptyDirVolumeSource{},
130					},
131				})
132			}
133			for ci := range role.Template.Spec.Containers {
134				container := &role.Template.Spec.Containers[ci]
135				if container.Name == SidecarName {
136					continue
137				}
138				if !utils.HasVolumeMount(container.VolumeMounts, DefaultAdapterVolumeName, DefaultAdapterMountPath) {
139					container.VolumeMounts = append(container.VolumeMounts, corev1.VolumeMount{
140						Name:      DefaultAdapterVolumeName,
141						MountPath: DefaultAdapterMountPath,
142					})
143				}
144			}
145	
146			// Build the sidecar container using shared logic
147			runtimeContainer := buildRuntimeSidecarContainer(sidecarImage, currentEngineType)
148	
149			// Inject sidecar at the beginning
150			role.Template.Spec.Containers = append(
151				[]corev1.Container{runtimeContainer},
152				role.Template.Spec.Containers...,
153			)
154		}
155	}
